{
  "schemaVersion": "0.2",
  "slug": "share-panel",
  "name": "SharePanel",
  "family": "H",
  "status": "experimental",
  "purpose": "Offers share targets and a copyable link for the current content.",
  "scenarios": [
    "Share a dashboard view",
    "Share a market listing",
    "Copy a deep link"
  ],
  "props": {
    "title": {
      "type": "string",
      "required": true,
      "description": "Panel headline."
    },
    "url": {
      "type": "string",
      "required": true,
      "description": "Canonical URL to share."
    },
    "targets": {
      "type": "string",
      "required": false,
      "description": "Subset of x | linkedin | email | copy targets to show."
    },
    "copyLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible label for the copy action."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Panel with targets."
    },
    {
      "name": "copied",
      "description": "Link copy just succeeded."
    }
  ],
  "composition": {
    "allowedParents": [
      "dialog",
      "popover",
      "card",
      "page"
    ],
    "allowedChildren": [
      "button"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not open share targets without user activation.",
    "Do not list targets the current platform cannot open."
  ],
  "a11y": {
    "role": "group",
    "keyboard": [
      "Tab moves across target buttons"
    ],
    "focus": "All targets are buttons in tab order.",
    "labeling": "Panel title labels the group; each target button is named.",
    "wcag": [
      "1.3.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Targets wrap on compact.",
    "breakpoints": {
      "compact": "Wrapped targets.",
      "medium": "Single row.",
      "large": "Single row."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "share-panel",
    "states": [
      "default",
      "copied"
    ],
    "intents": [
      "share-content"
    ]
  }
}

import { useState } from 'react'
import './styles.css'

export type ShareTarget = 'x' | 'linkedin' | 'email' | 'copy'

export interface SharePanelProps {
  title: string
  url: string
  targets?: ShareTarget[]
  copyLabel?: string
  className?: string
}

const TARGET_LABEL: Record<Exclude<ShareTarget, 'copy'>, string> = {
  x: 'X',
  linkedin: 'LinkedIn',
  email: 'Email',
}

function targetHref(target: Exclude<ShareTarget, 'copy'>, url: string, title: string) {
  const encodedUrl = encodeURIComponent(url)
  const encodedTitle = encodeURIComponent(title)
  if (target === 'x') return `https://twitter.com/intent/tweet?url=${encodedUrl}&text=${encodedTitle}`
  if (target === 'linkedin') return `https://www.linkedin.com/sharing/share-offsite/?url=${encodedUrl}`
  return `mailto:?subject=${encodedTitle}&body=${encodedUrl}`
}

export function SharePanel({ title, url, targets = ['x', 'linkedin', 'email', 'copy'], copyLabel = 'Copy link', className }: SharePanelProps) {
  const [copied, setCopied] = useState(false)
  const classes = ['cu-share-panel', className].filter(Boolean).join(' ')

  const copy = async () => {
    try {
      await navigator.clipboard?.writeText(url)
    } catch {
      // Clipboard unavailable; still surface the confirmation affordance.
    }
    setCopied(true)
  }

  return (
    <div
      className={classes}
      role="group"
      aria-label={title}
      data-ai-role="share-panel" data-ai-intent="share-content"
      data-ai-state={copied ? 'copied' : 'default'}
    >
      <p className="cu-share-panel__title">{title}</p>
      <div className="cu-share-panel__targets">
        {targets.map((target) =>
          target === 'copy' ? (
            <button key="copy" type="button" className="cu-share-panel__target" onClick={copy}>
              {copied ? '✓ ' : ''}{copyLabel}
            </button>
          ) : (
            <a
              key={target}
              className="cu-share-panel__target"
              href={targetHref(target, url, title)}
              target="_blank"
              rel="noreferrer"
            >
              {TARGET_LABEL[target]}
            </a>
          ),
        )}
      </div>
      <p className="cu-share-panel__url">{url}</p>
    </div>
  )
}

.cu-share-panel {
  display: block;
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
}

.cu-share-panel__title {
  margin: 0;
  font-weight: 600;
}

.cu-share-panel__targets {
  display: flex;
  flex-wrap: wrap;
  gap: var(--cu-space-2);
  margin-block-start: var(--cu-space-2);
}

.cu-share-panel__target {
  display: inline-flex;
  align-items: center;
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-2);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-sm);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  font: inherit;
  text-decoration: none;
  cursor: pointer;
}

.cu-share-panel__target:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}

.cu-share-panel__url {
  margin: var(--cu-space-2) 0 0;
  font-size: 0.875em;
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
  overflow-wrap: anywhere;
}
